        String line = br.readLine();
        if (line == null) return;
        List<char[]> list = new ArrayList<>();
        List<Character> row = new ArrayList<>();
        boolean inStr = false;
        for (int i = 0; i < line.length(); i++) {
            char c = line.charAt(i);
            if (c == '"') inStr = !inStr;
            else if (inStr && (c == 'X' || c == '.')) row.add(c);
            else if (!inStr && c == ']') {
                if (!row.isEmpty()) {
                    char[] arr = new char[row.size()];
                    for (int j = 0; j < row.size(); j++) arr[j] = row.get(j);
                    list.add(arr);
                    row.clear();
                }
            }
        }
        char[][] board = list.toArray(new char[0][]);
        System.out.println(new Solution().countBattleships(board));
    }
}

